CREATE OR REPLACE FUNCTION private.seller_can_take_payment(p_seller uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select not private.payout_readiness_required()
      or coalesce((
        select p.payouts_enabled
            or (p.stripe_account_id is not null
                and p.payout_details_submitted
                and p.payout_restricted_at is null)
        from public.profiles p where p.id = p_seller
      ), false);
$function$;

comment on function private.seller_can_take_payment(p_seller uuid) is 'Whether this seller can publish and be bought from: payouts enabled, or Stripe setup started (details submitted) and not restricted at day 14, or job_config.payments_mode is ''stub'' (20261108100000).';

